return {
[11170] = {id=11170,name="Test at Sea",level=10,requiredLevel=10,faction="horde",expansion=2,zoneID=495,description="We've just received word of reinforcements coming to the aid of the Alliance forces. Their timing couldn't be better! We're in sore need of test subjects and these North Fleet reservists will do nicely! Take these plague vials with you and speak to Camille, the Bat Handler. Tell her you need to commandeer a riding bat for a special assignment for us. Once you're at sea, drop the vials on the reinforcement fleet. I can't wait to see the results!",rewardGold=53500,rewardXP=1415,rewardItems={33349,35839,35841,35842,35843},rewardChoices={35841,35842,35843,35839},starts={{npcID=24126,x=0.786,y=0.29,zoneID=495}},ends={{npcID=24126,x=0.786,y=0.29,zoneID=495}},coords={x=0.786,y=0.29,source="quest_giver",zoneID=495},questType="standard"},
[11307] = {id=11307,name="Field Test",level=10,requiredLevel=10,faction="horde",expansion=2,zoneID=495,description="Now that we have a strain of the plague that has adapted to vrykul carriers, we really ought to test it on our specimens in Halgrind. If all goes according to plan, they will disintegrate immediately as the plague devours their innards! You will find Halgrind north of here. Our plaguebringers are deploying the previous strain there - shouldn't be hard to spot.",rewardGold=53500,rewardXP=1415,rewardItems={33621,35857,35858},rewardChoices={35857,35858},starts={{npcID=24251,x=0.536,y=0.664,zoneID=495}},ends={{npcID=24251,x=0.536,y=0.664,zoneID=495}},coords={x=0.536,y=0.664,source="quest_giver",zoneID=495},questType="standard"},
[11719] = {id=11719,name="A Suitable Test Subject",level=10,requiredLevel=10,faction="horde",expansion=2,zoneID=3537,description="So we've got this pollinated bloodspore flower and nobody to test its effects on. Say, would you perhaps be interested in rubbing this on your skin and letting me observe? What's the worst that could happen anyway? Don't you worry, ! Just take this sample and rub it all over your face.",rewardXP=175,starts={{npcID=25381,x=0.52,y=0.524,zoneID=3537}},ends={{npcID=25381,x=0.52,y=0.524,zoneID=3537}},coords={x=0.52,y=0.524,source="quest_giver",zoneID=3537},questType="standard"},
[12300] = {id=12300,name="Test of Mettle",level=15,requiredLevel=15,faction="alliance",expansion=2,zoneID=394,description="Alright, friend. You've done us a favor or two, but that's not the true test of a person's courage. Around these parts, you're not a real hunter unless you wear your prey's skin. Sergei unsheathes his skinning knife and hands it to you.> The leader of those motherless orcs attacking our town is called Bonesnap; you'll find him at a camp further northwest. That's right. You're going to skin the monster.",rewardXP=1570,starts={{npcID=27486,x=0.264,y=0.358,zoneID=394}},ends={{npcID=27497,x=0.218,y=0.3,zoneID=394}},coords={x=0.264,y=0.358,source="quest_giver",zoneID=394},questType="standard"},
[12520] = {id=12520,name="Rhino Mastery: The Test",level=20,requiredLevel=20,faction="both",expansion=2,zoneID=3711,description="No rough landing is going to stop ol' Hemet from mastering the largest game Sholazar has to offer. In the wilds northwest of the camp, the jungles are ruled by the mighty shardhorn rhino . You can prove your worth to the expedition, , by showing me that you're tough enough to face down those powerful beasts.",rewardGold=105000,rewardXP=2765,starts={{npcID=27986,x=0.27,y=0.586,zoneID=3711}},ends={{npcID=27986,x=0.27,y=0.586,zoneID=3711}},coords={x=0.27,y=0.586,source="quest_giver",zoneID=3711},questType="standard"},
[12645] = {id=12645,name="The Taste Test",level=20,requiredLevel=20,faction="both",expansion=2,zoneID=3711,description="And now for the moment of truth! I've always wanted to say that. Normally, I'd debut a new drink at a banquet, but we can't have one in the middle of the jungle. Instead, just take samples to a few trusted friends and return with their comments. Let's see, we'll definitely want Hemet Nesingwary 's opinion, and Hadrius Harlowe 's, too. They're here in camp. You'll want to head over to Lakeside Landing, near the center of the Basin and offer Tamara Wobblesprocket a taste.",rewardGold=210000,rewardXP=3455,rewardItems={39520,38697},starts={{npcID=29157,x=0.268,y=0.6,zoneID=3711}},ends={{npcID=29157,x=0.268,y=0.6,zoneID=3711}},coords={x=0.268,y=0.6,source="quest_giver",zoneID=3711},questType="standard"},
}
end)
